-- Images
-- A project's images, by name.
--
-- Everything in a project's images folder -- in any subfolder -- gets a
-- name: its file name, made into a Lua identifier ("my-logo.png" is
-- my_logo). The names are written to scripts/designed/images.lua as a
-- module returning name -> full path:
--
--     local images = require("designed.images")
--     window:setIcon(images.logo)
--
-- Code says *which* image, never *where*. Moving logo.png from brand/ to
-- icons/ rewrites that one generated file and nothing that refers to
-- images.logo has to change -- which is the whole point: nobody keeps
-- track of what lives in which folder. The module is regenerated whenever
-- the folder changes, through Limer's image manager or behind its back.
--
-- Names are unique across the whole tree. The image manager keeps them so
-- when it brings files in; a clash made outside it is settled here, by
-- prefixing the folder (icons/save.png beside save.png is icons_save).

local fs = require("limekit.fs")

local FS = fs.FileSystem
local Images = {}

local SUFFIXES = { png = true, jpg = true, jpeg = true, gif = true, bmp = true,
                   svg = true, ico = true, webp = true }

local RESERVED = {}
for word in ([[and break do else elseif end false for function goto if in
    local nil not or repeat return then true until while]]):gmatch("%S+") do
    RESERVED[word] = true
end

--- The identifier for a file name's stem. Agrees with ImageBrowser's
--- name_key on the Python side, so both name a file the same way.
function Images.key(stem)
    local k = stem:gsub("[^%w_]", "_")
    k = k:gsub("_+", "_")
    k = k:gsub("^_+", "")
    k = k:gsub("_+$", "")
    if k == "" then k = "image" end
    if k:match("^%d") then k = "_" .. k end
    return k
end

function Images.folder(project)
    return FS.joinPaths(project, "images")
end

function Images.modulePath(project)
    return FS.joinPaths(FS.joinPaths(FS.joinPaths(project, "scripts"), "designed"), "images.lua")
end

--- Every image in the project: { { key = "logo", path = "brand/logo.png" } },
--- sorted by key. `path` is relative to the images folder, with forward
--- slashes, as res.Resources.images takes it.
function Images.scan(project)
    local root = Images.folder(project)
    local found = {}
    local function walk(dir, rel)
        if not FS.exists(dir) then return end
        for _, entry in ipairs(FS.listFolder(dir)) do
            local name = tostring(entry)
            if name:sub(1, 1) ~= "." then
                local full = FS.joinPaths(dir, name)
                local relPath = rel == "" and name or (rel .. "/" .. name)
                if FS.isFolder(full) then
                    walk(full, relPath)
                else
                    local stem, ext = name:match("^(.*)%.([^.]+)$")
                    if stem and SUFFIXES[ext:lower()] then
                        found[#found + 1] = { stem = stem, path = relPath, folder = rel }
                    end
                end
            end
        end
    end
    walk(root, "")
    table.sort(found, function(a, b) return a.path < b.path end)

    -- Shallowest first, so a clash is settled in favour of the file nearer
    -- the top: save.png keeps "save", icons/save.png becomes icons_save.
    table.sort(found, function(a, b)
        local da, db = select(2, a.path:gsub("/", "")), select(2, b.path:gsub("/", ""))
        if da ~= db then return da < db end
        return a.path < b.path
    end)
    local used, list = {}, {}
    for _, image in ipairs(found) do
        local key = Images.key(image.stem)
        if used[key] then
            key = Images.key(image.folder:gsub("/", "_") .. "_" .. image.stem)
            local n = 2
            local base = key
            while used[key] do key = base .. "_" .. n; n = n + 1 end
        end
        used[key] = true
        list[#list + 1] = { key = key, path = image.path }
    end
    table.sort(list, function(a, b) return a.key < b.key end)
    return list
end

local function field(key)
    if RESERVED[key] then return ("[%q]"):format(key) end
    return key
end

--- How code refers to an image: images.logo, or images["end"].
function Images.reference(key)
    if RESERVED[key] then return ("images[%q]"):format(key) end
    return "images." .. key
end

--- The source of scripts/designed/images.lua for a scan.
function Images.module(list)
    local lines = {
        "-- GENERATED by Limer from the project's images folder. Do not edit:",
        "-- it is rewritten whenever an image is added, moved, renamed or deleted.",
        "--",
        "-- Refer to images by name -- images.logo -- not by path, and moving a",
        "-- file to another folder in the images manager never breaks a reference.",
        'local res = require("limekit.res")',
        "",
        "return {",
    }
    for _, image in ipairs(list) do
        lines[#lines + 1] = ("    %s = res.Resources.images(%q),"):format(field(image.key), image.path)
    end
    lines[#lines + 1] = "}"
    lines[#lines + 1] = ""
    return table.concat(lines, "\n")
end

-- name -> full path, for the project last refreshed.
local current = { project = nil, list = {}, paths = {} }
local observers = {}

--- Called with (list) after every refresh.
function Images.observe(fn)
    observers[#observers + 1] = fn
end

function Images.list() return current.list end

--- The project the names belong to, or nil before one is open.
function Images.project() return current.project end

--- The full path of a named image in the current project, or nil.
function Images.path(key)
    return key and current.paths[key] or nil
end

--- The name of the image at a path relative to the images folder, or nil.
function Images.keyFor(relPath)
    for _, image in ipairs(current.list) do
        if image.path == relPath then return image.key end
    end
    return nil
end

--- Re-scans the project, rewrites the module if what it says has changed,
--- and tells every observer. Writes nothing for a project with no images
--- and no module yet, so a project that never uses images gets no file.
function Images.refresh(project)
    if not project then return {} end
    local list = Images.scan(project)
    local paths = {}
    for _, image in ipairs(list) do
        paths[image.key] = FS.joinPaths(Images.folder(project), image.path)
    end
    current = { project = project, list = list, paths = paths }

    local target = Images.modulePath(project)
    local source = Images.module(list)
    local exists = FS.exists(target)
    if #list > 0 or exists then
        -- Only when the content changes: the file is inside the watched
        -- project, so an unconditional write would trigger the watcher,
        -- which would refresh, which would write...
        local ok, old = pcall(FS.readFile, target)
        if not (exists and ok and old == source) then
            local dir = target:match("^(.*)[/\\][^/\\]+$")
            if dir and not FS.exists(dir) then FS.createFolder(dir) end
            pcall(FS.writeFile, target, source)
        end
    end

    for _, fn in ipairs(observers) do fn(list) end
    return list
end

return Images
